def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        # Check if this is a symlink
        if new_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[new_path]

            # Resolve target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative target - relative to directory containing the link
                if new_path == '/':
                    current = '/'
                else:
                    current = new_path.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace remaining components with target components + rest
            components = target_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just move to this path
        current = new_path
        i += 1

    # Remove trailing slash (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

